        '<a href="/tools/subnet-calculator/" class="btn btn-secondary" style="font-size: 0.85rem;">Subnet Calculator &rarr;</a>',
        '<a href="/find-router-ip/" class="btn btn-secondary" style="font-size: 0.85rem;">Find Router IP &rarr;</a>',
